import logging

from typing import Optional, Union, List  # noqa: F401

from taf.config.testline.cloud_hosting import DeploymentVnfStack  # noqa: F401
from taf.config.testline.cloud_hosting import DeploymentNetworkStack  # noqa: F401
from taf.config.testline.cloud_hosting import DeploymentFlavorStack  # noqa: F401
from taf.config.testline.cloud_hosting import DeploymentSecurityGroupStack  # noqa: F401
from taf.config.testline.gnb.cu import CU  # noqa: F401

from taf.internal.robot_typecasts import time_to_seconds

from .image import Image, ImageData
from .connection import connect
from .network import Network
from .server import Server
from .stack import Stack, StackStatus
from .configuration import ConfigurationModifier


class openstack(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    DEFAULT_NETWORKS_TO_UPDATE = ('oam', 'fronthaul', 'backhaul')

    def __init__(self):
        self._connection = None

    def connect(self, controller_ip, username='admin', password='uteadmin',
                os_tenant='admin', port=5000, version='v3', protocol='https'):
        """Initializes a connection to control node. Controller ip can be
        either an IPv4 or IPv6 address"""
        self._connection = connect(
            controller_ip,
            port=port,
            version=version,
            username=username,
            password=password,
            os_tenant=os_tenant,
            protocol=protocol)

    def get_flavor_params(self, vnf_prefix=''):
        return Stack(self._connection).get_flavor_params(vnf_prefix=vnf_prefix)

    def create_flavor_stack(self, stack_name, yaml_path, params={}, files={}):
        self._deprecate_old_create_keyword()
        Stack(self._connection).create_flavor_stack(
            stack_name=stack_name,
            yaml_path=yaml_path,
            params=params,
            files=files)

    def create_ext_net_stack(self, stack_name, yaml_path, params, files={}):
        self._deprecate_old_create_keyword()
        Stack(self._connection).create_ext_net_stack(
            stack_name=stack_name,
            yaml_path=yaml_path,
            params=params,
            files=files)

    def create_deploy_stack(
            self, stack_name, yaml_path, params, files={}, inject_robot=False,
            robot_account_parameter_name=Stack.ROBOT_ACCOUNT_PARAM_NAME,
            bts_env_file_name=Stack.DEFAULT_BTS_ENV_FILE_NAME):
        self._deprecate_old_create_keyword()
        Stack(self._connection).create_deploy_stack(
            stack_name=stack_name,
            yaml_path=yaml_path,
            params=params,
            files=files,
            inject_robot=inject_robot,
            robot_account_parameter_name=robot_account_parameter_name,
            bts_env_file_name=bts_env_file_name)

    def create_stack(
            self,
            stack,  # type: Union[DeploymentNetworkStack, DeploymentVnfStack, DeploymentFlavorStack, DeploymentSecurityGroupStack]
            inject_robot=False,  # type: bool
            robot_account_parameter_name=None,  # type: str
            wait=True,  # type: bool
            rollback=False  # type: bool
    ):
        """ Creates a stack.

        :param stack: an instance of DeploymentNetworkStack, DeploymentVnfStack
            or DeploymentFlavorStack, DeploymentSecurityGroupStack
        :param inject_robot: whether to inject robot account to environment in
            case of DeploymentVnfStack
        :param robot_account_parameter_name: name of robot account
            (used only if inject_robot is True and stack is an instance
            of DeploymentVnfStack)
        :param wait: Whether to wait for the create to finish
        :param rollback: Enable rollback on create failure

        :return: list of outputs of created stack
        """
        if inject_robot:
            if robot_account_parameter_name is None:
                robot_account_parameter_name = Stack.ROBOT_ACCOUNT_PARAM_NAME
        elif robot_account_parameter_name is not None:
            raise ValueError(
                "Passing robot_account_parameter_name is not valid, "
                "because `inject_robot` is False.")

        return Stack(self._connection).create_stack(
            stack=stack,
            inject_robot=inject_robot,
            robot_account_parameter_name=robot_account_parameter_name,
            wait=wait,
            rollback=rollback)

    def update_network_ids(self, deploy_env, net_env,
                           network_list=DEFAULT_NETWORKS_TO_UPDATE):
        """ Update network ids with ids of networks that have been found based
        on `net_env` properties.
        Note that `net_env` parameter should be passed from testline's
        configuration: `tl.cbts.heat.net`.
        If `network_opt`s `name` parameter is not sufficient for
        determining a single network,
        then the program will try to find the network by pattern, which by
        default is equal to
        "{vnf_name}-{name}_net-v{ip_ver}". Note that all variables must
        be found in `network_opts`s network dictionary (except for `vnf_name`,
        which should be found in `network_opts`).

        :param deploy_env: an object obtained from testline configuration - `tl.cbts.heat.bts`
        :param net_env: an object obtained from testline configuration - `tl.cbts.heat.net`
        :param network_list: list of networks which identifiers are to be
        updated, defaults to a list: 'oam', 'fronthaul' and 'backhaul'.

        There's an assumption that networks in `network_opts` are in
        following order: oam, fronthaul, backhaul.

        Raises NetworkNotFound if no network has been found with given name.
        Raises AmbiguousInstanceName if more than one network with
        given name was found.
        """
        Network(self._connection).update_ids(deploy_env=deploy_env,
                                             net_env=net_env,
                                             network_list=network_list)

    def update_ids_using_stack_output(
            self,
            ext_net_stack_name_or_id,
            deployment_vnf_stack,
            env_key_to_network_name_map=Network.ENV_KEY_TO_NETWORK_NAME_MAP,
            cu=None):
        # type: (Union[str, List[str]], DeploymentVnfStack, dict, CU) -> None
        """ Update the vnf stack's environment parameters responsible
        for network identifiers.

        ##### For backward compatibility, the method accepts any of the following configuration:
        1. `deployment_vnf_stack.configuration_data` is `None` and `cu` is passed (recommended)
        2. `deployment_vnf_stack.configuration_data` is loaded and `cu` is passed
        3. `deployment_vnf_stack.configuration_data` is `None` and `cu` is *not* passed
        4. `deployment_vnf_stack.configuration_data` is loaded and `cu` is *not* passed

        ##### Note about the 1st and 2nd option:
        The method will update the network identifiers according to VLAN id mapping defined in `CU`.
        `cu` attributes (namely: `backhaul_site_oam_ip`, `f1m`, `f1c`, `x2c`,
        `f1u`, `x2u`, `s1u`, `s1c`, `tracing`) should be instances of `NetworkAddress` with filled `vlan_id`.

        ##### Note about the 3rd and 4th option:
        The method won't work correctly if the name of the network created before
        doesn't contain the stack's environment key (e.g. environment
        key is 'backhaul' and full network name is 'vBTS-bhaul_net_T01_net-v4',
        the correct network name should be 'vBTS-backhaul_net_T01_net-v4' in
        this case).

        The method does the following if `cu` parameter is `None`:
        * Load vnf stack's environment configuration as dictionary
        (if it's not already loaded)
        * Load external network stack's output as dictionary
        * For each unfilled parameter with name "X" in the configuration:
            If "X" is inside one of the output's keys (which should happen
            only if "X" is a network parameter key), then fill
            the parameter value with the output's value for that key.

        :param ext_net_stack_name_or_id: name(s) of external networks stack that
        has the network names and identifiers provided in its output
        :param deployment_vnf_stack: DeploymentVnfStack instance
        :param env_key_to_network_name_map: mapping between environment keys
        to short network name
        :param cu: instance of `taf.config.testline.CU` class
        """
        Network(self._connection).update_ids_using_stack_output(
            ext_net_stack_name_or_id=ext_net_stack_name_or_id,
            deployment_vnf_stack=deployment_vnf_stack,
            env_key_to_name=env_key_to_network_name_map,
            cu=cu)

    def add_image_to_glance(self, cbts, image_url, visibility=Image.IMAGE_VISIBILITY):
        """ Adds an image to glance from the source specified in image_uri.

        :param cbts: Cloud BTS object from testline configuration
        :param image_url: uri path to image source; should have a
               prefix of "http(s)://" if it's from a remote
               and "file://" if it's from a local storage.
        :param visibility: set the image visibility, can be: 'public' or 'private'.
               For specification check the Glance image visibility design documentation.
               Defaults to 'public'.
        """
        warn_msg = "This keyword is deprecated. " \
                   "Use `add_image` keyword instead."
        logging.warning(warn_msg)
        Image(self._connection).upload(cbts=cbts, image_url=image_url, visibility=visibility)

    def add_image(self,
                  deployment_vnf_stack,
                  image_url,
                  visibility=Image.IMAGE_VISIBILITY,
                  image_parameter_to_update=ConfigurationModifier.IMAGE_PARAMETER,
                  disk_format=Image.DEFAULT_DISK_FORMAT):
        # type: (DeploymentVnfStack, str, Optional[str], Optional[str], Optional[str]) -> Union[bool, None]
        """ Adds an image to glance from the source specified in image_uri.
        Note that this keyword will update stack's configuration_data with
        image name. It will raise an UploadFail if uploading to glance fails.

         :param deployment_vnf_stack: an instance of DeploymentVnfStack;
               Raises TypeError if configuration_data attribute is
               not initialized. Otherwise, the `image` key will be filled.
         :param image_url: uri path to image source; should have a
               prefix of "http(s)://" if it's from a remote
               and "file://" if it's from a local storage
         :param visibility: image visibility, can be: 'public' or 'private';
               for specification check the Glance image
               visibility design documentation; defaults to 'public'.
         :param image_parameter_to_update: parameter key to update in vnf
               stack's configuration_data.
         :param disk_format: disk format supported by openstack, defaults to qcow2
         """
        Image(self._connection).add(
            deployment_vnf_stack=deployment_vnf_stack,
            image_url=image_url,
            visibility=visibility,
            image_parameter_to_update=image_parameter_to_update,
            disk_format=disk_format)
        return True

    def add_image_from_file(self,
                            deployment_vnf_stack,
                            image_path,
                            visibility=Image.IMAGE_VISIBILITY,
                            image_parameter_to_update=ConfigurationModifier.IMAGE_PARAMETER,
                            disk_format=Image.DEFAULT_DISK_FORMAT,
                            timeout=600):
        # type: (DeploymentVnfStack, str, Optional[str], Optional[str], Optional[str]) -> Union[bool, None]
        """
        Adds an image to glance from the file specified in image_path.
        Note that this keyword will update stack's configuration_data with
        image name.
        Keyword will wait for image ACTIVE status for given timeout (defaults to 600seconds).

         :param deployment_vnf_stack: an instance of DeploymentVnfStack;
               Raises TypeError if configuration_data attribute is
               not initialized. Otherwise, the `image` key will be filled.
         :param image_path: path to image file; can be relative or absolute
         :param visibility: image visibility, can be: 'public' or 'private';
               for specification check the Glance image
               visibility design documentation; defaults to 'public'.
         :param image_parameter_to_update: parameter key to update in vnf
               stack's configuration_data.
         :param disk_format: disk format supported by openstack, defaults to qcow2
         :param timeout: defaults to 600 seconds
         :raises Timeout: if ACTIVE status not reached within given timeout
         """
        timeout = time_to_seconds(timeout)
        Image(self._connection).add_from_file(
            deployment_vnf_stack=deployment_vnf_stack,
            image_path=image_path,
            visibility=visibility,
            image_parameter_to_update=image_parameter_to_update,
            disk_format=disk_format,
            timeout=timeout)
        return True

    def remove_old_stacks_if_necessary(self,
                                       deploy_name,
                                       ext_net_name,
                                       flavors_name):
        Stack(self._connection).remove_old_stacks_if_necessary(
            deploy_name=deploy_name,
            ext_net_name=ext_net_name,
            flavors_name=flavors_name)

    def remove_stack(self, stack, wait=True):
        # type: (Union[DeploymentNetworkStack, DeploymentVnfStack, DeploymentFlavorStack, DeploymentSecurityGroupStack], bool) -> None
        """ Removes a stack.

        :param stack: an instance of DeploymentNetworkStack, DeploymentVnfStack
         or DeploymentFlavorStack, DeploymentSecurityGroupStack
        :param wait: whether to wait for the stack removal to finish, defaults to True
        """
        Stack(self._connection).remove(stack, wait=wait)

    def remove_image_from_glance(self, image_url, disk_format=Image.DEFAULT_DISK_FORMAT):
        """ Removes indicated image from artifactory.

        :param image_url: An URL or name of image to be deleted.
        :param disk_format: Extension of image to be removed. Defaults to "qcow2"
        """
        Image(self._connection).remove(image_url, disk_format=disk_format)

    def get_referenced_files(self, cfg_dir):
        return Stack(self._connection).get_referenced_files(cfg_dir=cfg_dir)

    def get_instance_status(self, instance_name):
        return Server(self._connection).get_status(instance_name=instance_name)

    def does_image_exist(self, name_or_id):
        # type: (str) -> bool
        return Image(self._connection).does_image_exist(name_or_id)

    def get_image_status(self, name_or_id):
        # type: (str) -> str
        return Image(self._connection).get_status(name_or_id)

    def get_image_name(self, name_or_id):
        # type: (str) -> str
        return Image(self._connection).get_name(name_or_id)

    def get_image_id_by_name(self, name):
        # type: (str) -> str
        return Image(self._connection).get_id_by_name(name)

    def protect_image(self, name_or_id):
        # type: (str) -> None
        """
        Set the protection flag to an image. It will not fail if
        the flag is already set.

        :param name_or_id: name or id of the Image
        """
        Image(self._connection).protect(name_or_id)

    def unprotect_image(self, name_or_id):
        # type: (str) -> None
        """
        Unset the protection flag from an image. It will not fail if
        the flag is already unset.

        :param name_or_id: name or id of the Image
        """
        Image(self._connection).unprotect(name_or_id)

    def add_image_tag(self, name_or_id, tag):
        # type: (str, str) -> None
        """
        Add a tag to an image. It will not fail if the tag is already added.

        :param name_or_id: name or id of the Image
        :param tag: tag given as string
        """
        Image(self._connection).add_tag(name_or_id, tag)

    def remove_image_tag(self, name_or_id, tag):
        # type: (str, str) -> None
        """
        Remove a tag from an image. It will not fail if the tag is already removed.

        :param name_or_id: name or id of the Image
        :param tag: tag given as string
        """
        Image(self._connection).remove_tag(name_or_id, tag)

    def wait_for_stack_creation(self, name_or_id, timeout):
        # type: (str, Union[str, float, int]) -> None
        """
        Waits for stack creation for a given time.

        :param name_or_id: name or id of the Stack
        :param timeout: can be given as an int, float or in Robot Framework's time format
        :raises: InvalidStatus when status failed
        :raises: Timeout if the status of the Stack is not expected after given time.
        """
        timeout = time_to_seconds(timeout)
        Stack(self._connection).wait_for_stack_status(
            name_or_id,
            status=StackStatus.CREATE_COMPLETE,
            timeout=timeout)

    def wait_for_stack_deletion(self, name_or_id, timeout):
        # type: (str, Union[str, float, int]) -> None
        """
        Waits for stack deletion for a given time.

        :param name_or_id: name or id of the Stack
        :param timeout: can be given as an int, float or in Robot Framework's time format
        :raises: InvalidStatus when status failed
        :raises: Timeout if the status of the Stack is not expected after given time.
        """
        timeout = time_to_seconds(timeout)
        Stack(self._connection).wait_for_stack_status(
            name_or_id,
            status=StackStatus.DELETE_COMPLETE,
            timeout=timeout)

    def start_server(self, server_name_or_id):
        """ Finds a server instance and starts it.

        :param server_name_or_id: name or ID of the server to start.
        :raises OpenstackException: if the found server is not in SHUTOFF state.
        """
        return Server(self._connection).start(server_name_or_id)

    def stop_server(self, server_name_or_id):
        """ Finds a server instance and shuts it off.

        :param server_name_or_id: name or ID of the server to stop.
        :raises OpenstackException: if the found server is not in ACTIVE state.
        """
        return Server(self._connection).stop(server_name_or_id)

    def reboot_server_soft(self, server_name_or_id):
        """ Finds a server instance and makes a soft reboot.
        If found server instance is not in ACTIVE state,
        raises OpenstackException.
        If no server instance could be found, raises ResourceNotFound.
        If server name was passed and it is not unique,
        raises DuplicateResource.
        Returns server instance's state after reboot has been done. """
        return Server(self._connection).reboot_soft(server_name_or_id)

    def reboot_server_hard(self, server_name_or_id):
        """ Finds a server instance and makes a hard reboot.
        If found server instance is not in ACTIVE state,
        raises OpenstackException.
        If no server instance could be found, raises ResourceNotFound.
        If server name was passed and it is not unique,
        raises DuplicateResource.
        Returns server instance's state after reboot has been done. """
        return Server(self._connection).reboot_hard(server_name_or_id)

    def _deprecate_old_create_keyword(self):
        warn_msg = "This keyword is deprecated. " \
                   "Use `create_stack` keyword instead."
        logging.warning(warn_msg)

    def get_images(self, **attributes):
        # type: (**str) -> List[ImageData]
        """
        Return images with given attributes. If attributes are not
        given, all images will be returned.

        :param attributes: e.g. name='AirFrameVirtualized-5.3135.577'
        :return: list of items which contains `status`, `id` and `name`
        """
        return Image(self._connection).images(**attributes)

    def get_stack_status(self, name_or_id):
        # type: (str) -> str
        return Stack(self._connection).get_status(name_or_id)

    def wait_for_image_status(self, name_or_id, status, timeout):
        # type: (str, str,  Union[str, float, int]) -> None
        """
        Waits for Image status for a given time. Raises `Timeout` if
        the status of the Image is not expected after given time.

        Possible statuses:
        * queued
        * saving
        * active
        * deactivated
        * killed
        * pending_delete
        * deleted (use also when you want to wait until image is not visible in Glance)

        :param name_or_id: name or id of the image
        :param status: expected status
        :param timeout: can be given as an int, float or in Robot Framework's time format
        """
        timeout = time_to_seconds(timeout)
        status = status.lower()
        Image(self._connection).wait_for_status(name_or_id, status, timeout)
